plist.dict:
  Label
  @LABEL@
  ProgramArguments

    /bin/bash
    @FM_ROOT@/bin/fm-model-picker-daily.sh
    @VERB@

  EnvironmentVariables

    FM_HOME
    @FM_HOME@
@EXTRA_ENV@
    PATH
    @PATH@

  WorkingDirectory
  @FM_HOME@
  RunAtLoad
  <@RUN_AT_LOAD@/>
  StartInterval
  @INTERVAL@
  ProcessType
  Background
  StandardOutPath
  @FM_HOME@/state/.model-picker-daily-@VERB@.launchd.log
  StandardErrorPath
  @FM_HOME@/state/.model-picker-daily-@VERB@.launchd.log
